/**
 * {{ombox}} (other pages message box) styles
 *
 * @source https://www.mediawiki.org/wiki/MediaWiki:Gadget-enwp-boxes.css
 * @revision 2021-07-15
 */
table.ombox {
	margin: 4px 10%;
	border-collapse: collapse;
	/* Default "notice" gray */
	border: 1px solid #a2a9b1;
	background-color: #f8f9fa;
	color: #333;
	box-sizing: border-box;
}

/* An empty narrow cell */
.ombox td.mbox-empty-cell {
	border: none;
	padding: 0;
	width: 1px;
}

/* The message body cell(s) */
.ombox th.mbox-text,
.ombox td.mbox-text {
	border: none;
	/* 0.9em left/right */
	padding: 0.25em 0.9em;
	/* Make all mboxes the same width regardless of text length */
	width: 100%;
}

/* The left image cell */
.ombox td.mbox-image {
	border: none;
	text-align: center;
	/* 0.9em left, 0px right */
	/* @noflip */
	padding: 2px 0 2px 0.9em;
}

/* The right image cell */
.ombox td.mbox-imageright {
	border: none;
	text-align: center;
	/* 0px left, 0.9em right */
	/* @noflip */
	padding: 2px 0.9em 2px 0;
}

table.ombox-notice {
	/* Gray */
	border-color: #a2a9b1;
}

table.ombox-speedy {
	/* Pink */
	background-color: #fee7e6;
	color: #333;
}

table.ombox-speedy,
table.ombox-delete {
	/* Red */
	border-color: #b32424;
	border-width: 2px;
}

table.ombox-content {
	/* Orange */
	border-color: #f28500;
}

table.ombox-style {
	/* Yellow */
	border-color: #fc3;
}

table.ombox-move {
	/* Purple */
	border-color: #9932cc;
}

table.ombox-protection {
	/* Gray-gold */
	border-color: #a2a9b1;
	border-width: 2px;
}

/**
 * {{ombox|small=1}} styles
 *
 * These ".mbox-small" classes must be placed after all other
 * ".ombox" classes. "html body.mediawiki .ombox"
 * is so they apply only to other page message boxes.
 *
 * @source https://www.mediawiki.org/wiki/MediaWiki:Gadget-enwp-boxes.css
 * @revision 2021-07-15
 */

/* For the "small=yes" option. */
html body.mediawiki .ombox.mbox-small {
	clear: right;
	float: right;
	margin: 4px 0 4px 1em;
	box-sizing: border-box;
	width: 238px;
	font-size: 88%;
	line-height: 1.25em;
}

@media screen {
	html.skin-theme-clientpref-night table.ombox {
	    background-color: transparent;
	    color: inherit;
	}
}

@media screen and (prefers-color-scheme: dark) {
    /* automatic mode */
    html.skin-theme-clientpref-os table.ombox {
    	background-color: transparent;
    	color: inherit;
    }
}

@media screen and (max-width: 720px) {
  table.ombox {
	margin: 4px auto;
  }
}

/** {{Shared Template Warning}}
 * This TemplateStyles page is separately used for [[Template:Navbar]]
 * because of course there are two versions of the same template.
 * Be careful when adjusting styles accordingly.
 */
.navbar {
	display: inline;
	font-size: 88%;
	font-weight: normal;
}

.navbar ul {
	display: inline;
	white-space: nowrap;
}

.navbar li {
	word-spacing: -0.125em;
}

/* Navbar styling when nested in navbox */
.navbox .navbar {
	display: block;
	font-size: 100%;
}

.navbox-title .navbar {
	/* @noflip */
	float: left;
	/* @noflip */
	text-align: left;
	/* @noflip */
	margin-right: 0.5em;
	width: 6em;
}

.ts-doc-sandbox .mbox-image	{
	padding:.75em 0 .75em .75em;
}

.ts-doc-doc {
	clear: both;
	background-color: #eaf3ff;
	color: var(--color-base, #202122);
	border: 1px solid #a3caff;
	margin-top: 1em;
	border-top-left-radius: 2px;
	border-top-right-radius: 2px;
}

.ts-doc-header {
	background-color: #cbd6f6;
	color: var(--color-base, #202122);
	padding: .642857em 1em .5em;
	border-top-left-radius: 2px;
	border-top-right-radius: 2px;
}

.ts-doc-heading {
	display: inline-block;
	padding-left: 30px;
	background: center left / 24px 24px no-repeat;
	/* @noflip */
	background-image: url( //upload.wikimedia.org/wikipedia/commons/f/fb/OOjs_UI_icon_puzzle-ltr.svg );
	height: 24px;
	line-height: 24px;
	font-size: 13px;
	font-weight: 600;
	letter-spacing: 1px;
	text-transform: uppercase;
}

.ts-doc-header .ts-tlinks-tlinks {
	line-height: 24px;
	margin-left: 0;
}

.ts-doc-header .ts-tlinks-tlinks a {
	color: var(--color-progressive, #36c);
}

.ts-doc-header .ts-tlinks-tlinks a:active {
	color: var(--color-progressive--active, #233566);
}

.ts-doc-header .ts-tlinks-tlinks a:visited {
	color: var(--color-visited, #6a60b0);
}

.ts-doc-header .ts-tlinks-tlinks a:visited:active {
	color: var(--color-visited--active, #233566);
}

.ts-doc-content {
	padding: .214286em 1em;
}

.ts-doc-content:after {
	content: '';
	clear: both;
	display: block;
}

.ts-doc-content > :first-child {
	margin-top: .5em;
}

.ts-doc-content > :last-child {
	margin-bottom: .5em;
}

.ts-doc-footer {
	background-color: #eaf3ff;
	color: var(--color-base, #202122);
	border: 1px solid #a3caff;
	padding: .214286em 1em;
	margin-top: .214286em;
	font-style: italic;
	border-bottom-left-radius: 2px;
	border-bottom-right-radius: 2px;
}

@media all and (min-width: 720px) { 
	.ts-doc-header .ts-tlinks-tlinks {
		float: right;
	}
}

html.skin-theme-clientpref-night .ts-doc-header {
	background-color: #3056a9;
}

html.skin-theme-clientpref-night .ts-doc-heading {
	background-image: url( '//upload.wikimedia.org/wikipedia/commons/d/d3/OOjs_UI_icon_puzzle-ltr-invert.svg' );	
}

html.skin-theme-clientpref-night .ts-doc-doc,
html.skin-theme-clientpref-night .ts-doc-footer {
	background-color: #1b223d;
}

@media screen and (prefers-color-scheme: dark) {
	html.skin-theme-clientpref-os .ts-doc-header {
		background-color: #3056a9;
	}

	html.skin-theme-clientpref-os .ts-doc-heading {
		background-image: url( '//upload.wikimedia.org/wikipedia/commons/d/d3/OOjs_UI_icon_puzzle-ltr-invert.svg' );	
	}

	html.skin-theme-clientpref-os .ts-doc-doc,
	html.skin-theme-clientpref-os .ts-doc-footer {
		background-color: #1b223d;
	}
}

/* Styling for [[Template:Mono]] */
.monospaced {
	/* Keep it like this: "monospace, monospace". Those are the rules from [[w:WP:MONO]]. */
	font-family: monospace, monospace;
}

.nowrap,
.nowrap a:before,
.nowrap .selflink:before {
	white-space: nowrap;
}

